"use client";

/**
 * Cursor path: a pointer walks a path of waypoints over a screen, easing from
 * point to point, and clicks where a point asks for it with a press and a ripple.
 *
 * Written by Better Design. Painted from the theme prop; with no children it
 * walks over a placeholder settings card that answers each click.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import type { ReactNode } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const PRESS_FRAMES = 8;
const RIPPLE_FRAMES = 22;

/** One stop on the path. */
export interface CursorPoint {
  /** Across the frame, 0 to 1. */
  x: number;
  /** Down the frame, 0 to 1. */
  y: number;
  /** Frame the pointer arrives here. */
  at: number;
  /** Click on arrival. */
  click?: boolean;
}

export interface CursorPathProps {
  /** Waypoints in the order the pointer visits them. */
  points?: CursorPoint[];
  /** What the pointer moves over. A placeholder settings card when absent. */
  children?: ReactNode;
  /** Labels on the placeholder card. */
  heading?: string;
  toggleLabel?: string;
  buttonLabel?: string;
  /** What the placeholder button says once its click lands. */
  savedLabel?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const DEFAULT_POINTS: CursorPoint[] = [
  { x: 0.3, y: 0.82, at: 0 },
  { x: 0.64, y: 0.5, at: 34, click: true },
  { x: 0.58, y: 0.63, at: 70, click: true },
  { x: 0.68, y: 0.74, at: 100 },
];

/** Placeholder hit areas, as fractions of the frame: the switch and the button. */
const TOGGLE = { x0: 0.6, x1: 0.68, y0: 0.46, y1: 0.54 };
const BUTTON = { x0: 0.33, x1: 0.67, y0: 0.58, y1: 0.67 };

/** The frame of the first click inside a box, or Infinity. */
function clickIn(points: CursorPoint[], box: typeof TOGGLE): number {
  const hit = points.find((p) => p.click && p.x >= box.x0 && p.x <= box.x1 && p.y >= box.y0 && p.y <= box.y1);
  return hit ? hit.at : Number.POSITIVE_INFINITY;
}

function PlaceholderCard({ theme, frame, points, heading, toggleLabel, buttonLabel, savedLabel }: { theme: VideoTheme; frame: number; points: CursorPoint[]; heading: string; toggleLabel: string; buttonLabel: string; savedLabel: string }) {
  const on = easings.out(progress(frame, clickIn(points, TOGGLE), 10));
  const pressAt = clickIn(points, BUTTON);
  const press = frame >= pressAt ? Math.sin(Math.min(1, (frame - pressAt) / PRESS_FRAMES) * Math.PI) : 0;
  const saved = progress(frame, pressAt + 4, 16);
  const outT = easings.out(Math.min(1, saved * 2));
  const inT = easings.out(Math.max(0, saved * 2 - 1));
  const bar = (w: string, h: number) => <div style={{ width: w, height: h, borderRadius: h / 2, background: withAlpha(theme.foreground, 0.1) }} />;
  return (
    <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: 760, padding: 56, borderRadius: theme.radius * 2.4, background: theme.card, border: `1px solid ${theme.border}`, boxShadow: "0 40px 100px oklch(0 0 0 / 0.12)", display: "flex", flexDirection: "column", gap: 40 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={{ fontSize: 44, fontWeight: 700, letterSpacing: "-0.03em", color: theme.cardForeground }}>{heading}</div>
          {bar("62%", 16)}
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "26px 0", borderTop: `1px solid ${theme.border}`, borderBottom: `1px solid ${theme.border}` }}>
          <div style={{ fontSize: 32, fontWeight: 500, color: theme.cardForeground }}>{toggleLabel}</div>
          <div style={{ position: "relative", width: 104, height: 60, borderRadius: 30, padding: 6, background: theme.muted, border: `1px solid ${theme.border}` }}>
            <div style={{ position: "absolute", inset: -1, borderRadius: 30, background: theme.primary, opacity: on }} />
            <div style={{ position: "relative", width: 48, height: 48, borderRadius: 24, background: "oklch(1 0 0)", transform: `translateX(${on * 44}px)`, boxShadow: "0 2px 6px oklch(0 0 0 / 0.2)" }} />
          </div>
        </div>
        <div
          style={{
            height: 84,
            borderRadius: 42,
            background: theme.primary,
            color: theme.primaryForeground,
            fontSize: 32,
            fontWeight: 600,
            display: "grid",
            placeItems: "center",
            transform: `scale(${1 - press * 0.04})`,
          }}
        >
          <span style={{ gridArea: "1 / 1", textAlign: "center", opacity: 1 - outT, transform: `translateY(${outT * -10}px)` }}>{buttonLabel}</span>
          <span style={{ gridArea: "1 / 1", textAlign: "center", opacity: inT, transform: `translateY(${(1 - inT) * 10}px)` }}>✓ {savedLabel}</span>
        </div>
      </div>
    </AbsoluteFill>
  );
}

/** A pointer that walks a path over its children and clicks at marked points. */
export function CursorPath({
  points = DEFAULT_POINTS,
  children,
  heading = "Notifications",
  toggleLabel = "Weekly summary",
  buttonLabel = "Save changes",
  savedLabel = "Saved",
  theme: themeOverride,
  font,
}: CursorPathProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const path = [...points].sort((a, b) => a.at - b.at);

  // Position: ease between the two waypoints around this frame.
  let x = path[0]?.x ?? 0.5;
  let y = path[0]?.y ?? 0.5;
  for (let i = 1; i < path.length; i++) {
    const a = path[i - 1];
    const b = path[i];
    if (frame < a.at) break;
    const t = easings.inOut(progress(frame, a.at, b.at - a.at));
    x = a.x + (b.x - a.x) * t;
    y = a.y + (b.y - a.y) * t;
  }

  const clicks = path.filter((p) => p.click);
  const pressing = clicks.find((p) => frame >= p.at && frame < p.at + PRESS_FRAMES);
  const press = pressing ? Math.sin(((frame - pressing.at) / PRESS_FRAMES) * Math.PI) : 0;
  const appear = easings.out(progress(frame, 0, 10));

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      {children ?? <PlaceholderCard theme={theme} frame={frame} points={path} heading={heading} toggleLabel={toggleLabel} buttonLabel={buttonLabel} savedLabel={savedLabel} />}
      {clicks.map((p, i) => {
        const t = progress(frame, p.at, RIPPLE_FRAMES);
        if (t <= 0 || t >= 1) return null;
        const r = easings.out(t) * 70;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x * W - r,
              top: p.y * H - r,
              width: r * 2,
              height: r * 2,
              borderRadius: "50%",
              border: `3px solid ${withAlpha(theme.primary, 0.7 * (1 - t))}`,
              background: withAlpha(theme.primary, 0.14 * (1 - t)),
            }}
          />
        );
      })}
      <svg
        width={44}
        height={56}
        viewBox="0 0 22 28"
        style={{
          position: "absolute",
          left: x * W - 3,
          top: y * H - 2,
          opacity: appear,
          transform: `scale(${1 - press * 0.18})`,
          transformOrigin: "3px 2px",
          filter: "drop-shadow(0 6px 10px oklch(0 0 0 / 0.25))",
        }}
      >
        <path d="M1.5 1.5 L1.5 22.5 L7 17.5 L10.5 25.5 L14 24 L10.5 16.2 L18 16 Z" fill={theme.foreground} stroke={theme.background} strokeWidth={1.6} strokeLinejoin="round" />
      </svg>
    </AbsoluteFill>
  );
}
